import{_ as e,c as t,o as s,af as p}from"./chunks/framework.BKeRpnBD.js";const h=JSON.parse('{"title":"爻辰第十五","description":"杭氏易學 - 爻辰第十五","frontmatter":{"title":"爻辰第十五","description":"杭氏易學 - 爻辰第十五"},"headers":[],"relativePath":"classics/hangshi/016.md","filePath":"classics/hangshi/016.md"}'),r={name:"classics/hangshi/016.md"};function i(n,a,c,_,o,l){return s(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="爻辰第十五" tabindex="-1">爻辰第十五 <a class="header-anchor" href="#爻辰第十五" aria-label="Permalink to “爻辰第十五”">​</a></h1><p>先天八卦，以陰陽升降，應日月之晦朔弦望，於是乎有納甲。因而重之，為六十四卦。卦有六爻，卦納幹而爻納支，於是乎有爻辰。辰者天度十二宮之次舍。而地支之十二，與天度相應者也。漢人言爻辰者，有鄭氏，有京氏，其說不同。鄭氏以乾陽坤陰，十二爻順逆交錯，以應十二月。而又以六十四卦之爻，合乾坤，分二十八宿之度數、星象合卦爻之象，以釋經。其書久佚，僅自《李氏集解》，及各經註疏採集其說，但存其梗概而已。有清戴氏棠，據《甘石星經》、《開元佔經》等書，按六十四卦之《彖》、《象》、《繫辭》，有以星象名義，或形似相類，援鄭例而補之，名《爻辰補》。然於經義象數，均未有當，無足採焉。</p><p>京氏納辰為古今術家所遵用，證之於《彖》、《象》十翼，多能相合。有與經義相發明，為經學家所不能道者。始知黃帝五甲六子三元九宮，實探陰陰造化之秘，明天人之際。以濟世利民者，固不僅卜筮之用也。康成生於漢季，施、孟、梁丘之《易》，已多失傳。獨費氏，因其說簡約而獨存。康成亦有所不足，故採取殘缺之緯書，兼及五行律歷星象，以釋卦爻，固費《易》之所無，或亦三家之遺義也。惜其書又亡。致三代之《易》，不能盡見於今。猶幸京《易》雖亡，而八宮世應納音納甲之數，猶得貫通，得與《周易》相參證。乃學者又畏其繁瑣，目為蕪穢，必盡棄之，以自詡擴清之功，《易》道又何自明哉！</p><p>京氏六爻納辰圖</p><p>卦納甲而爻納辰，京氏以陽順陰逆，交錯為用。以乾坤為綱，六子分乾坤之爻，以次相推。仍以本宮為體，而六爻所納之支，視其與本宮生克，以為親疏遠近利害之分。圖如下：</p><p>陽卦納陽，於陽支皆順行。陰卦納陰，於陰支皆逆行。乾內納甲，外納壬，支起子，子寅辰午申戌順行。坤內納乙，外納癸，支起未，未巳卯醜亥酉逆行。陰陽交錯，以相合為用者也。故乾生震，震為長子。長子代父納庚，而六爻之支，與乾全同。子寅辰午申戌皆順行也。坎中男，得乾中爻，乾內中寅，坎納戊，故初爻自寅起，為戊寅，戊辰，戊午，戊申，戊戌，戊子也。艮少男，得乾之上爻。乾內三辰，艮納丙，故初爻自辰起為丙辰，丙午，丙戌，丙子，丙寅也。坤生長女為巽，長女代母，而納不起於醜，而起於未，與震襲乾不同者，此男女之別，陰陽之分。女以出為歸，故自內出外。由四爻起未，五巳上卯，而反至初為醜二為亥三為酉也。離為中女，得坤中爻，故於外中五爻起未。兌為少女，得坤上爻，故於外上起未，皆未巳卯醜亥酉，與巽同例也。季彭山不知陰陽之別，妄改坤起乙丑。又有不分陰陽，不知本末，妄改乾為甲子，甲戌，甲午，甲寅，甲辰者，皆絕無意義。學者不可好奇喜新，為所誤也。</p><p>六十四卦，八純卦外，一世至六世，皆取本宮納甲。見者為飛，不見者為伏。遊魂歸魂十六卦，不取本宮為伏。分舉爻位如下：</p><p>晉以艮為伏，而取艮四爻者，以遊魂仍為四爻變。而晉上之離，由剝上之艮變來者也。故不以本宮不以對宮而取艮。大有下卦之離，由晉下卦之坤變來者也。歸魂為三爻，故取坤三。餘卦仿此。</p><p>鄭氏爻辰，亦以陰陽六爻，相間用事。乾辰子寅辰午申戌，其次與京氏同，而坤則為未酉亥醜卯巳與京氏異。蓋陰陽雖間一位，而皆順行。蓋以十二律相生為據也。他卦分乾坤之爻，亦分乾坤之辰，不論納甲。</p>',9)])])}const f=e(r,[["render",i]]);export{h as __pageData,f as default};
